<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $resource->title }} · {{ $brand['name'] }}</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css"><style>body{margin:0;background:#020b12;color:#eefaff;font-family:Inter,system-ui,sans-serif}.wrap{width:min(900px,calc(100% - 28px));margin:auto}.back{display:inline-flex;gap:8px;color:#59d8f2;text-decoration:none;font-size:12px;margin-top:35px}.hero{padding:55px 0 25px}.ey{color:#45d1f0;text-transform:uppercase;letter-spacing:.16em;font-size:10px}.hero h1{font-size:clamp(34px,6vw,58px);margin:12px 0}.muted{color:#8daab5;line-height:1.8}.article{border:1px solid rgba(70,210,240,.16);background:linear-gradient(145deg,#092736,#03161f);border-radius:20px;padding:clamp(20px,5vw,42px);line-height:1.9;color:#c9dce2}.article img{max-width:100%;border-radius:14px}.related{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin:35px 0 70px}.rel{padding:18px;border:1px solid rgba(70,210,240,.13);border-radius:15px;color:#dff8ff;text-decoration:none}.rel small{color:#58d5ee}@media(max-width:600px){.related{grid-template-columns:1fr}}</style></head><body><main class="wrap"><a class="back" href="{{ route('resources.index') }}"><i class="fa-solid fa-arrow-left"></i> All resources</a><section class="hero"><span class="ey">Resource</span><h1>{{ $resource->title }}</h1>@if($resource->published_at)<p class="muted">Published {{ $resource->published_at->format('F j, Y') }}</p>@endif</section><article class="article">@if($resource->image_path)<img src="{{ asset('storage/'.$resource->image_path) }}" alt="{{ $resource->title }}" loading="lazy">@endif<div>{!! $resource->content !!}</div></article>@if($related->count())<section><h2>Related resources</h2><div class="related">@foreach($related as $item)<a class="rel" href="{{ route('resources.show',$item->slug) }}"><small><i class="fa-solid fa-file